mapper.select:
/* CastFcltMapper.retrieveDuplicateSmltFcltNmList */ SELECT A.SMLT_FCLT_NM FROM PMOWN.TN_PM_SMLT_PSG_FCLT A WHERE 1 = 1 AND A.SMLT_FCLT_NM IS NOT NULL AND (
(A.SMLT_FCLT_NM = #{item.smltFcltNm} AND A.PSG_FCLT_CD != #{item.psgFcltCd})
)

mapper.update:
/* CastFcltMapper.updateSmltFcltNm */
UPDATE PMOWN.TN_PM_SMLT_PSG_FCLT
SET SMLT_FCLT_NM = #{smltFcltNm},
    LAST_MDFR_ID = #{loginUserId},
    LAST_MDFR_IP_ADDR = #{loginIpAddr},
    LAST_MDFCN_DT = CURRENT_TIMESTAMP
WHERE 1 = 1
AND PSG_FCLT_CD = #{psgFcltCd}
/* 화면이 보고 있던 터미널의 시설만 고친다 (엉뚱한 터미널 코드가 섞여 오면 0건) */
AND TMNL_ID = #{fcltTmnlId}
